def _is_public_program(self, program: ProgramRecord) -> bool:
    """Check if program is from public company.

    Args:
        program: ProgramRecord.

    Returns:
        True if ticker is present and company marked public.
    """
    if not program.ticker:
        return False
    if program.company_public is None:
        return False
    return bool(program.company_public)

